import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { createLicenseInventory } from './license-bundle-inventory.mjs';

test('inventory contains only emitted modules and includes worker dependencies', () => {
  const root = mkdtempSync(path.join(tmpdir(), 'rdf4j-license-inventory-'));
  const outputFile = path.join(root, 'target/licensing/npm-modules.json');
  const inventory = createLicenseInventory({ projectRoot: root, outputFile });
  const main = inventory.mainPlugin;
  main.buildStart();
  const worker = inventory.workerPlugin();
  worker.generateBundle({}, { 'worker.js': { type: 'chunk', modules: {
    [path.join(root, 'node_modules/@viz-js/viz/dist/viz.js')]: {},
  } } });
  main.generateBundle({}, { 'app.js': { type: 'chunk', modules: {
    [path.join(root, 'node_modules/react/index.js')]: {},
    [path.join(root, 'node_modules/@viz-js/viz/dist/viz.js') + '?worker']: {},
    [path.join(root, 'src/main.ts')]: {},
    '\0vite:helper': {},
  } }, 'source.map': { type: 'asset', source: '{}' } });
  main.writeBundle();
  assert.deepEqual(JSON.parse(readFileSync(outputFile, 'utf8')), [
    'node_modules/@viz-js/viz/dist/viz.js', 'node_modules/react/index.js',
  ]);
  assert.ok(!readFileSync(outputFile, 'utf8').includes(root), 'do not publish build-host paths');
});

test('a new build clears prior dependency evidence and emits deterministic ordering', () => {
  const root = mkdtempSync(path.join(tmpdir(), 'rdf4j-license-inventory-'));
  const outputFile = path.join(root, 'target/npm-modules.json');
  mkdirSync(path.dirname(outputFile), { recursive: true });
  writeFileSync(outputFile, '["stale"]');
  const inventory = createLicenseInventory({ projectRoot: root, outputFile });
  inventory.mainPlugin.buildStart();
  const modules = { [path.join(root, 'node_modules/z/index.js')]: {},
    [path.join(root, 'node_modules/a/index.js')]: {} };
  inventory.mainPlugin.generateBundle({}, { 'app.js': { type: 'chunk', modules } });
  inventory.mainPlugin.writeBundle();
  const first = readFileSync(outputFile, 'utf8');
  inventory.mainPlugin.buildStart();
  inventory.mainPlugin.generateBundle({}, { 'app.js': { type: 'chunk', modules } });
  inventory.mainPlugin.writeBundle();
  assert.equal(readFileSync(outputFile, 'utf8'), first);
  assert.deepEqual(JSON.parse(first), ['node_modules/a/index.js', 'node_modules/z/index.js']);
});

test('dependencies outside the npm project fail rather than lose provenance', () => {
  const root = mkdtempSync(path.join(tmpdir(), 'rdf4j-license-inventory-'));
  const inventory = createLicenseInventory({ projectRoot: root, outputFile: path.join(root, 'modules.json') });
  inventory.mainPlugin.buildStart();
  assert.throws(() => inventory.mainPlugin.generateBundle({}, { 'app.js': { type: 'chunk', modules: {
    '/outside/node_modules/something/index.js': {},
  } } }), /outside/);
});
